def flatten(lst: list, depth: int = None) -> list:
    """
    Flatten a nested list up to a given depth.
    If depth is None, flatten completely.
    depth=1 flattens one level only.
    """
    def _flatten(lst, current_depth, max_depth):
        result = []
        for element in lst:
            if isinstance(element, list):
                if max_depth is not None and current_depth == max_depth:
                    result.append(element)
                else:
                    if max_depth is None:
                        sub_result = _flatten(element, current_depth + 1, None)
                    else:
                        sub_result = _flatten(element, current_depth + 1, max_depth)
                    result.extend(sub_result)
            else:
                result.append(element)
        return result

    if depth is None:
        return _flatten(lst, 0, None)
    else:
        return _flatten(lst, 0, depth)

def flatten(lst, depth=None):
    def flatten_helper(lst, current_depth, max_depth):
        result = []
        for item in lst:
            if isinstance(item, list):
                if max_depth is None or current_depth < max_depth:
                    result.extend(flatten_helper(item, current_depth + 1, max_depth))
                else:
                    result.append(item)
            else:
                result.append(item)
        return result

    if depth is None:
        return flatten_helper(lst, 0, None)
    else:
        return flatten_helper(lst, 0, depth)
